import{_ as t,o as h,c as i,a2 as o}from"./chunks/framework.BBd5PKnH.js";const d=JSON.parse('{"title":"Venus (Kim Tinh)","description":"","frontmatter":{},"headers":[],"relativePath":"astro/planets/venus.md","filePath":"astro/planets/venus.md"}'),a={name:"astro/planets/venus.md"};function u(s,n,e,r,c,g){return h(),i("div",null,[...n[0]||(n[0]=[o('<h1 id="venus-kim-tinh" tabindex="-1">Venus (Kim Tinh) <a class="header-anchor" href="#venus-kim-tinh" aria-label="Permalink to &quot;Venus (Kim Tinh)&quot;">​</a></h1><blockquote><p>Quy ước: <strong>[Sách]</strong> = nội dung có trong các trang bạn chụp. <strong>[Bổ sung]</strong> = kiến thức traditional astrology nói chung, mình thêm vào để nối với phần đã học. Phần [Bổ sung] nên đối chiếu lại với các chương sau của sách.</p><p><strong>Lưu ý:</strong> ảnh bạn gửi chỉ có đoạn cuối của Venus (tên thơ ca, thần thoại, bản chất cốt lõi). <strong>Đoạn đầu</strong> (ý nghĩa chi tiết, cơ thể, màu, vị, condition tốt/xấu theo sách) chưa có trong ảnh, nên các phần đó dưới đây là [Bổ sung]. Khi có đoạn đầu, hãy đối chiếu và sửa lại.</p></blockquote><hr><h2 id="_1-vi-tri-cua-venus-trong-he-thong" tabindex="-1">1. Vị trí của Venus trong hệ thống <a class="header-anchor" href="#_1-vi-tri-cua-venus-trong-he-thong" aria-label="Permalink to &quot;1. Vị trí của Venus trong hệ thống&quot;">​</a></h2><ul><li>Venus là <strong>lesser benefic</strong> (benefic nhỏ) [bổ sung, nối với bài benefic/malefic]</li><li>Venus là benefic của <strong>phe đêm</strong> (nocturnal): lá số đêm thì Venus in sect, hoạt động thuận lợi hơn</li><li>Venus và Mars đối lập về tính chất: Venus kết nối, hòa hợp; Mars tách ra, va chạm</li></ul><p><strong>Hiểu đơn giản:</strong> Venus giống người hòa giải và người tạo không khí dễ chịu. Có Venus tốt, mọi thứ trơn tru. Venus quá đà thì thành chiều chuộng bản thân, buông thả.</p><hr><h2 id="_2-phan-co-trong-sach-sach" tabindex="-1">2. Phần có trong sách [Sách] <a class="header-anchor" href="#_2-phan-co-trong-sach-sach" aria-label="Permalink to &quot;2. Phần có trong sách [Sách]&quot;">​</a></h2><h3 id="ten-va-than-thoai" tabindex="-1">Tên và thần thoại <a class="header-anchor" href="#ten-va-than-thoai" aria-label="Permalink to &quot;Tên và thần thoại&quot;">​</a></h3><ul><li>Tên thơ ca: <em>Phōsphoros</em> (= người mang đuốc). Sau này trong tiếng Latin là <em>Lucifer</em>, cũng nghĩa &quot;mang ánh sáng&quot;, ban đầu không liên quan đến quỷ</li><li>Inanna và Ishtar (Babylon): nữ thần tình yêu và sự màu mỡ của đất đai</li><li>Hy Lạp: ngôi sao của <strong>Aphroditē</strong>, nữ thần sắc đẹp và ham muốn</li></ul><h3 id="cot-loi" tabindex="-1">Cốt lõi <a class="header-anchor" href="#cot-loi" aria-label="Permalink to &quot;Cốt lõi&quot;">​</a></h3><ul><li>Bản chất (Valens): <strong>To magnetize</strong> (thu hút như nam châm), essence: <strong>love, desire, and beauty</strong></li><li>Archetype hiện đại: <strong>The Lover and Harmonizer</strong></li></ul><p><strong>Cách nhớ:</strong> Venus là &quot;lực hút&quot;. Con người, đồ vật, ý tưởng nào kéo được sự chú ý và thiện cảm đều mang dấu Venus.</p><hr><h2 id="_3-y-nghia-truyen-thong-noi-chung-bo-sung-can-đoi-chieu-voi-sach" tabindex="-1">3. Ý nghĩa truyền thống nói chung [Bổ sung, cần đối chiếu với sách] <a class="header-anchor" href="#_3-y-nghia-truyen-thong-noi-chung-bo-sung-can-đoi-chieu-voi-sach" aria-label="Permalink to &quot;3. Ý nghĩa truyền thống nói chung [Bổ sung, cần đối chiếu với sách]&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nhóm</th><th>Nội dung thường gặp</th></tr></thead><tbody><tr><td>Tính chất</td><td>Ấm và ẩm (nhẹ nhàng, nuôi dưỡng)</td></tr><tr><td>Con người</td><td>Phụ nữ, người yêu, vợ/chồng, người hòa nhã, người làm đẹp, nghệ sĩ</td></tr><tr><td>Chủ đề</td><td>Tình yêu, hôn nhân, ham muốn, sắc đẹp, nghệ thuật, âm nhạc, tiệc tùng, tình bạn</td></tr><tr><td>Vật chất</td><td>Đồng (kim loại truyền thống), đồ trang sức, nước hoa</td></tr><tr><td>Ngày</td><td>Thứ Sáu</td></tr></tbody></table><hr><h2 id="_4-essential-dignity-cua-venus-bo-sung" tabindex="-1">4. Essential dignity của Venus [Bổ sung] <a class="header-anchor" href="#_4-essential-dignity-cua-venus-bo-sung" aria-label="Permalink to &quot;4. Essential dignity của Venus [Bổ sung]&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Loại</th><th>Vị trí</th><th>Ý nghĩa dễ hiểu</th></tr></thead><tbody><tr><td>Domicile</td><td><strong>Taurus</strong> và <strong>Libra</strong></td><td>Ở nhà mình, thoải mái nhất</td></tr><tr><td>Exaltation</td><td><strong>Pisces</strong> (nổi tiếng là khoảng 27°)</td><td>Được tôn vinh, tình yêu bao dung</td></tr><tr><td>Triplicity</td><td>Nhóm <strong>đất</strong> và nhóm <strong>nước</strong>, Venus cai quản <strong>ban ngày</strong> (theo hệ Dorotheus, hệ phổ biến nhất; hãy đối chiếu bảng trong sách)</td><td>Có chỗ dựa vào ban ngày</td></tr><tr><td>Detriment</td><td><strong>Aries</strong> và <strong>Scorpio</strong></td><td>Đối diện nhà mình</td></tr><tr><td>Fall</td><td><strong>Virgo</strong></td><td>Đối diện nơi được tôn vinh</td></tr></tbody></table><p><strong>Ví dụ cụ thể:</strong></p><ul><li>Venus ở Taurus: yêu chậm, chắc, thích hưởng thụ giác quan (ăn, mặc, thiên nhiên)</li><li>Venus ở Pisces (exaltation): tình yêu bao dung, lãng mạn, giàu cảm xúc nghệ thuật</li><li>Venus ở Virgo (fall): khắt khe, hay phân tích và soi lỗi trong tình cảm, khó thoải mái buông lòng</li><li>Venus ở Scorpio (detriment): tình cảm mãnh liệt, đòi hỏi tuyệt đối, dễ chiếm hữu</li></ul><p>Nhắc lại từ Figure 3: Venus cai quản <strong>Taurus và Libra</strong>, cả hai sign này đều &quot;của Venus&quot; khi bạn tìm house ruler.</p><hr><h2 id="_5-sect-joy-phase-cua-venus-bo-sung" tabindex="-1">5. Sect, Joy, Phase của Venus [Bổ sung] <a class="header-anchor" href="#_5-sect-joy-phase-cua-venus-bo-sung" aria-label="Permalink to &quot;5. Sect, Joy, Phase của Venus [Bổ sung]&quot;">​</a></h2><ul><li><strong>Sect:</strong> benefic của phe đêm <ul><li>Lá số đêm: Venus <strong>in sect</strong>, thuận lợi hơn</li><li>Lá số ngày: Venus <strong>out of sect</strong>, vẫn là benefic nhưng kém nhịp nhàng hơn</li></ul></li><li><strong>Joy:</strong> <strong>House 5</strong> (tình yêu, con cái, vui chơi)</li><li><strong>Phase đặc biệt của Venus</strong> (liên quan trực tiếp tên <em>Phōsphoros</em>): <ul><li><strong>Oriental</strong> (mọc trước Sun, xuất hiện buổi sáng sớm): sao Mai, &quot;người mang đuốc&quot;. Truyền thống thường coi là chủ động, mạnh mẽ hơn</li><li><strong>Occidental</strong> (mọc sau Sun, xuất hiện buổi chiều tối): sao Hôm. Truyền thống thường coi là mềm hơn, thụ động hơn</li><li>Chi tiết giữa hai pha nằm ở chương solar phase, bạn hãy đối chiếu</li></ul></li><li><strong>Khoảng cách tối đa:</strong> Venus không bao giờ cách Sun quá khoảng 47°, nên không bao giờ đối (opposition) với Sun</li><li><strong>Retrograde:</strong> khoảng 6 tuần, lặp lại khoảng 18-19 tháng một lần: tình cảm, giá trị cá nhân, tiền bạc dễ bị xem xét lại</li><li><strong>Combust:</strong> Venus quá gần Sun bị lu mờ, đặc biệt đáng chú ý vì Venus luôn ở gần Sun</li></ul><hr><h2 id="_6-venus-tot-vs-xau-đoc-nhu-the-nao-bo-sung" tabindex="-1">6. Venus tốt vs xấu: đọc như thế nào [Bổ sung] <a class="header-anchor" href="#_6-venus-tot-vs-xau-đoc-nhu-the-nao-bo-sung" aria-label="Permalink to &quot;6. Venus tốt vs xấu: đọc như thế nào [Bổ sung]&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition tốt</th><th>Condition xấu</th></tr></thead><tbody><tr><td>Ở Taurus/Libra/Pisces; lá số đêm; đi thuận; không combust; nhận hỗ trợ từ Jupiter; không bị Saturn/Mars chiếu căng</td><td>Ở Aries/Scorpio/Virgo; lá số ngày; retrograde; combust; bị Mars hoặc Saturn square/opposition</td></tr><tr><td>Biểu hiện: dễ được yêu quý, quan hệ hài hòa, có gu thẩm mỹ, được hưởng thụ vừa phải</td><td>Biểu hiện: quan hệ trắc trở, buông thả, hưởng thụ quá đà, hoặc ngược lại thiếu thốn tình cảm</td></tr></tbody></table><p><strong>Insight:</strong> theo Valens (đã học ở note trước), benefic ở condition xấu thì mang lại &quot;reversals&quot; (đảo ngược). Với Venus, &quot;đảo ngược&quot; thường là thứ tốt đẹp bị dùng quá mức: yêu thành lụy, thích thành nghiện, đẹp thành phù phiếm.</p><p><strong>Insight về angularity:</strong></p><ul><li>Venus ở <strong>angular</strong> thì khuếch đại: condition tốt thì rất có duyên, dễ thấy; condition xấu thì rắc rối tình cảm hoặc chi tiêu cũng rõ rệt</li><li>Venus ở <strong>cadent</strong> thì kín đáo: giá trị và tình cảm có nhưng ít phô ra</li></ul><p><strong>Phối hợp Venus và Mars:</strong> hai hành tinh này kết hợp (conjunction, aspect) thường nói đến chuyện đam mê, cạnh tranh trong tình cảm, hoặc thu hút và đối đầu cùng lúc.</p><hr><h2 id="_7-khi-xem-la-so-cho-nguoi-khac-bo-sung" tabindex="-1">7. Khi xem lá số cho người khác [Bổ sung] <a class="header-anchor" href="#_7-khi-xem-la-so-cho-nguoi-khac-bo-sung" aria-label="Permalink to &quot;7. Khi xem lá số cho người khác [Bổ sung]&quot;">​</a></h2><h3 id="checklist-đanh-gia-venus" tabindex="-1">Checklist đánh giá Venus <a class="header-anchor" href="#checklist-đanh-gia-venus" aria-label="Permalink to &quot;Checklist đánh giá Venus&quot;">​</a></h3><ol><li>Lá số ngày hay đêm? (Venus in sect khi là đêm)</li><li>Venus ở sign nào? Có dignity hay debility?</li><li>Venus là sao Mai (oriental) hay sao Hôm (occidental)?</li><li>Venus có combust không? Có retrograde không?</li><li>Venus ở house nào? Angular hay cadent? Có phải house 5 (joy)?</li><li>Ai chiếu Venus? Mars/Saturn gây áp lực, Jupiter nâng đỡ</li><li>Venus cai quản house nào (Taurus và Libra nằm ở house mấy)?</li></ol><h3 id="venus-noi-đuoc-gi-ve-nguoi-đo" tabindex="-1">Venus nói được gì về người đó <a class="header-anchor" href="#venus-noi-đuoc-gi-ve-nguoi-đo" aria-label="Permalink to &quot;Venus nói được gì về người đó&quot;">​</a></h3><ul><li><strong>Cách yêu, cách tạo quan hệ, điều khiến họ thấy hấp dẫn</strong></li><li><strong>Giá trị thẩm mỹ, nghệ thuật, nơi họ thấy dễ chịu</strong></li><li><strong>Chuyện hôn nhân, tình cảm</strong> (cùng với house 7 và ruler của nó)</li><li><strong>Mối quan hệ với phụ nữ trong đời</strong> (ví dụ vợ, người yêu)</li></ul><h3 id="cach-noi-voi-nguoi-đoi-dien-vi-du" tabindex="-1">Cách nói với người đối diện (ví dụ) <a class="header-anchor" href="#cach-noi-voi-nguoi-đoi-dien-vi-du" aria-label="Permalink to &quot;Cách nói với người đối diện (ví dụ)&quot;">​</a></h3><ul><li>Venus tốt: &quot;Bạn có sức thu hút tự nhiên và dễ tạo thiện cảm. Trong tình cảm và các mối quan hệ, bạn thường được đón nhận.&quot;</li><li>Venus xấu: &quot;Chuyện tình cảm hoặc cách bạn nhìn nhận giá trị của bản thân có thể khiến bạn phải cân nhắc nhiều hơn. Điều giúp ích là đặt ranh giới rõ ràng và học cách nhận về xứng đáng với những gì mình cho đi.&quot;</li></ul><h3 id="luu-y" tabindex="-1">Lưu ý <a class="header-anchor" href="#luu-y" aria-label="Permalink to &quot;Lưu ý&quot;">​</a></h3><ul><li>Venus tốt không bảo đảm tình yêu thuận lợi, và Venus xấu không nghĩa là &quot;không có tình yêu&quot;. Lá số mô tả tiền đề, không phải kết cục</li><li>Đừng khẳng định chuyện ly hôn, ngoại tình, hay số lần kết hôn</li><li>Khi khách hỏi về hôn nhân, hãy xem house 7 và ruler của nó trước, Venus chỉ là một phần</li></ul><hr><h2 id="_8-loi-thuong-gap" tabindex="-1">8. Lỗi thường gặp <a class="header-anchor" href="#_8-loi-thuong-gap" aria-label="Permalink to &quot;8. Lỗi thường gặp&quot;">​</a></h2><ul><li>Cho rằng Venus &quot;luôn tốt&quot;. Venus xấu vẫn gây rắc rối, nhất là khi angular</li><li>Quên phase oriental/occidental của Venus</li><li>Quên Venus chỉ gần Sun, nên combust và under the beams xảy ra thường xuyên, cần kiểm tra mỗi lần xem</li></ul>',45)])])}const m=t(a,[["render",u]]);export{d as __pageData,m as default};
